interface ServiceVariant {
  id: string;
  name: string;
  price: string;
  duration: string;
}

interface Appointment {
  id: string;
  dateKey: string;
  dayName: string;
  time: string;
  durationMinutes?: number;
  saturdayApproval?: { status: 'pending' | 'accepted' | 'rejected'; reference: string; reason?: 'saturday' | 'assessment' | 'both' };
  advancePayment?: { amount: number; reference: string; status: 'pending' | 'confirmed' };
  clientName: string;
  phone: string;
  email: string;
  serviceCategory: string;
  serviceSubcategory: string;
  selectedVariant?: ServiceVariant | null;
  services?: { categoryId: string; categoryName: string; sub: SubService; variant: ServiceVariant | null }[];
  remindersStatus: {
    email48h: boolean;
    whatsapp48h: boolean;
    whatsapp24h: boolean;
    whatsapp2h: boolean;
  };
}

type StylingPolicy = 'included' | 'required' | 'not_applicable';

interface SubService {
  active?: boolean;
  requiresAssessment?: boolean;
  tonerPolicy?: StylingPolicy;
  isTonerService?: boolean;
  stylingPolicy?: StylingPolicy;
  isStylingService?: boolean;
  id: string;
  name: string;
  description: string;
  duration: string;
  price: string;
  bufferTime?: string;
  includesText?: string;
  achievedText?: string;
  priceType?: 'desde' | 'aprox' | 'fijo' | 'consultar';
  hasVariants?: boolean;
  variants?: ServiceVariant[];
  showAlertBadge?: boolean;
  alertText?: string;
}

interface CatalogCategory {
  id: string;
  code: string;
  title: string;
  icon?: string;
  subservices: SubService[];
}

interface ClientRecord {
  idNum: number;
  registroId: string;
  nombre: string;
  apellidos: string;
  fechaNacimiento: string;
  telefono: string;
  email: string;
  pinAcceso: string;
  diagnostico: string;
  ultimaVisita: string;
  proximaVisitaSugerida: string;
  formulasAplicadas: string;
  dniCapilar?: string;
  prescripcionCasa?: string;
  pastVisits?: { date: string; service: string; stylist: string; notes: string }[];
}

interface LostDemandRecord {
  id: string;
  date: string;
  clientName: string;
  serviceName: string;
  potentialValue: number;
  reason: 'sin_disponibilidad' | 'abandono_sin_servicio' | 'intento_fallido' | 'otro';
  clientNote: string;
  phone: string;
}

interface FeedbackRecord {
  id: string;
  date: string;
  clientName: string;
  rating: number;
  comment: string;
  type: 'detractor' | 'neutral' | 'promoter';
}

interface HolidayBlock {
  id: string;
  startDate: string;
  endDate: string;
  reason: string;
  type: 'vacaciones' | 'festivo';
}

